package com.example.investsmart.settlement;
import com.example.investsmart.dto.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class GroupedJournalChangeSummarizerTests {
    PeriodChargeAdapterTests fixture;GroupedJournalChangeSummarizer rules;
    @BeforeEach void setup(){fixture=new PeriodChargeAdapterTests();fixture.setup();var c=fixture.f.context;rules=new GroupedJournalChangeSummarizer(fixture.f.eligibilityAssessor,c.getBean(PeriodChargeGrouper.class),c.getBean(ChargeGroupSourceReconciler.class));}
    @AfterEach void close(){fixture.close();}
    BigDecimal amount(GroupedJournalChangeSummary p,int index){return p.buckets().get(index).change();}
    JournalPeriodEvidence replace(JournalPeriodEvidence p,GroupedChargeEvidence g,boolean limited){return new JournalPeriodEvidence(p.fromInclusive(),p.toExclusive(),p.initialization(),p.startsBeforeInitialization(),false,limited,p.fundingEvidenceTruncated(),p.entries(),p.limitations(),g);}
    @Test void actualWriterChargeAndOrdinaryRowsCountOnceWithoutChangingBalances(){var before=fixture.writer.balances();var result=rules.summarize(fixture.read());assertEquals(new BigDecimal("-20.00"),amount(result,0));assertEquals(new BigDecimal("0.00"),amount(result,1));assertFalse(result.fullAccountSummaryAvailable());assertEquals(before,fixture.writer.balances());assertThrows(UnsupportedOperationException.class,()->result.buckets().clear());}
    @Test void outsideChildrenAndChildOnlySelectionsWithholdBothScopes(){fixture.outsideChildrenAreOnlyContextAndOutsideParentLeavesChildrenVisible();var childOnly=rules.summarize(fixture.read());assertNull(amount(childOnly,0));assertNull(amount(childOnly,1));fixture.f.db.update("UPDATE settlement_journal SET occurred_at=? WHERE event_key='charge'",java.sql.Timestamp.from(SettlementFundsTests.BEFORE));fixture.f.db.update("UPDATE settlement_journal SET occurred_at=? WHERE reference_kind='CHARGE'",java.sql.Timestamp.from(SettlementFundsTests.BEFORE.plusSeconds(1)));var result=rules.summarize(fixture.read());assertNull(amount(result,0));assertTrue(result.buckets().getFirst().reasons().contains("CHARGE_CHILD_OUTSIDE_PERIOD"));}
    @Test void duplicateMissingAndStaleSourceBindingsNeverProducePartialSums(){var p=fixture.read();var g=p.chargeGrouping();var b=g.sourceEvidence().getFirst();var proof=b.sourceProof();var stale=new ChargeGroupSourceEvidence(b.status(),b.reason(),b.group(),new ChargeEvidence(proof.parent(),proof.children(),false,false,null));for(var sources:List.of(List.<ChargeGroupSourceEvidence>of(),List.of(b,b),List.of(stale))){var result=rules.summarize(replace(p,new GroupedChargeEvidence(g.status(),g.groups(),g.limitations(),sources),false));assertNull(amount(result,0));assertNull(amount(result,1));}}
    @Test void selectionLimitsMissingInputAndFreshSourceCorruptionWithhold(){assertNull(amount(rules.summarize(null),0));var p=fixture.read();assertNull(amount(rules.summarize(replace(p,p.chargeGrouping(),true)),0));fixture.f.db.update("UPDATE settlement_allocation_events SET amount=amount+1 WHERE action='SPEND'");assertNull(amount(rules.summarize(fixture.read()),0));}
    @Test void staleEligibilityCannotAuthorizeGroupedOutput(){var p=fixture.read();fixture.f.entry(1,"unknown","FUTURE_ACTION","1",SettlementFundsTests.BEFORE);var forged=fixture.read().withSummaryEligibility(p.summaryEligibility());var result=rules.summarize(forged);assertNull(amount(result,0));assertTrue(result.buckets().getFirst().reasons().contains("STALE_ELIGIBILITY"));}
    @Test void ordinaryCreditRefundPreservesUnknownVersusKnownBucket(){var writer=new SettlementFundsTests();writer.setup();writer.cash("deposit","20");var id=writer.pending("sale","30",SettlementFunds.CreditPolicy.REUSABLE);writer.reserve("reserve","30");writer.time(SettlementFundsTests.CUTOFF);writer.get(()->writer.funds.settle(1,id));writer.release("refund","30");try(var f=new JournalReportFixture(writer.fixture.source,false)){var p=f.context.getBean(JournalPeriodService.class).read(f.owner.getEmail(),SettlementFundsTests.BEFORE,SettlementFundsTests.CUTOFF.plusSeconds(1));var result=rules.summarize(p);assertNull(amount(result,0));assertEquals(new BigDecimal("0.00"),amount(result,1));}}
}
